using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class CurledMorayIntegration {
 const string Folder="Assets/UnderwaterArt/CurledMorayEncounter/",Scene="Assets/Scenes/Underwater_Realistic.unity";
 static SeaLife Actor()=>UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Single(a=>a.kind=="Moray");
 public static void Inspect(){
 AssetDatabase.Refresh();var imp=(ModelImporter)AssetImporter.GetAtPath(Folder+"CurledMoray.fbx");imp.animationType=ModelImporterAnimationType.Legacy;imp.importAnimation=true;imp.importCameras=false;imp.importLights=false;imp.isReadable=true;imp.materialImportMode=ModelImporterMaterialImportMode.None;imp.animationCompression=ModelImporterAnimationCompression.Off;var specs=imp.defaultClipAnimations;foreach(var c in specs){c.name=c.name.Split('|').Last();c.loopTime=true;c.wrapMode=WrapMode.Loop;}imp.clipAnimations=specs;imp.SaveAndReimport();
 EditorSceneManager.OpenScene(Scene);var actor=Actor();var sb=new System.Text.StringBuilder();foreach(var t in actor.GetComponentsInChildren<Transform>(true))sb.AppendLine(t.name+" local="+t.localPosition+" scale="+t.localScale+" components="+string.Join(",",t.GetComponents<Component>().Select(c=>c?c.GetType().Name:"missing")));sb.AppendLine("Position="+actor.transform.position+" rootScale="+actor.transform.lossyScale+" guard="+actor.GetComponent<ReefAnimalClearance>().animatedBody);
 foreach(var c in AssetDatabase.LoadAllAssetsAtPath(Folder+"CurledMoray.fbx").OfType<AnimationClip>())sb.AppendLine("CLIP "+c.name+" length="+c.length);
 Directory.CreateDirectory("Renders/CurledMorayEncounter");File.WriteAllText("Renders/CurledMorayEncounter/Before.txt",sb.ToString());Debug.Log("MORAY_INSPECTED "+sb);
 }
 static Vector3[] Points(SkinnedMeshRenderer s)=>OctopusRepairValidation.Points(s);
 static Bounds Envelope(Transform root,SkinnedMeshRenderer skin){var pts=Points(skin);var b=new Bounds(root.InverseTransformPoint(pts[0]),Vector3.zero);foreach(var p in pts)b.Encapsulate(root.InverseTransformPoint(p));return b;}
 public static void Run(){
 Inspect();var scene=EditorSceneManager.OpenScene(Scene);var life=Actor();var actor=life.transform;var oldPosition=actor.position;var oldGuard=life.GetComponent<ReefAnimalClearance>();var oldEnvelope=oldGuard.animatedBody;var oldColliders=actor.GetComponentsInChildren<Collider>(true);var oldRenderers=actor.GetComponentsInChildren<Renderer>(true);
 var protectedActors=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a!=life).ToDictionary(a=>a,a=>EditorJsonUtility.ToJson(a)+EditorJsonUtility.ToJson(a.transform));
 foreach(var motion in actor.GetComponentsInChildren<YellowMorayMotion>(true))motion.enabled=false;var wreck=actor.GetComponent<WreckCreature>();if(wreck)wreck.enabled=false;var fishMotion=actor.GetComponent<FishBodyMotion>();if(fishMotion)fishMotion.enabled=false;foreach(var a in actor.GetComponentsInChildren<Animation>(true)){a.enabled=false;a.playAutomatically=false;}foreach(var c in oldColliders)c.enabled=false;foreach(var r in oldRenderers)r.enabled=false;
 var previous=actor.Find("Prepared animated model");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);
 var wrapper=new GameObject("Prepared animated model");wrapper.transform.SetParent(actor,false);wrapper.transform.localRotation=Quaternion.Euler(0,180,0);wrapper.transform.localScale=Vector3.one*Mathf.Clamp(oldEnvelope.size.z,1.1f,1.8f);
 var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"CurledMoray.fbx"));model.transform.SetParent(wrapper.transform,false);PrefabUtility.UnpackPrefabInstance(model,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
 var clips=AssetDatabase.LoadAllAssetsAtPath(Folder+"CurledMoray.fbx").OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__")).ToArray();var rest=clips.Single(c=>c.name=="CurledRest");var swim=clips.Single(c=>c.name=="SwimStraight");var player=model.GetComponent<Animation>();if(!player)player=model.AddComponent<Animation>();player.AddClip(rest,rest.name);player.AddClip(swim,swim.name);player.clip=rest;player.enabled=false;player.playAutomatically=false;
 var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();skin.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/UnderwaterArt/MorayComparison/MoraySkin.mat");skin.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;skin.receiveShadows=false;skin.updateWhenOffscreen=false;
 rest.SampleAnimation(model,0);Bounds restBounds=Envelope(actor,skin),travel=restBounds,skinEnvelope=default;bool skinFirst=true;var bones=skin.bones;var restPose=new Quaternion[bones.Length];
 for(int phase=0;phase<8;phase++){rest.SampleAnimation(model,phase*.5f);restBounds.Encapsulate(Envelope(actor,skin));for(int i=0;i<bones.Length;i++)restPose[i]=bones[i].localRotation;swim.SampleAnimation(model,phase*.5f);var swimPose=bones.Select(b=>b.localRotation).ToArray();for(int blend=0;blend<=12;blend++){for(int i=0;i<bones.Length;i++)bones[i].localRotation=Quaternion.Slerp(restPose[i],swimPose[i],blend/12f);travel.Encapsulate(Envelope(actor,skin));foreach(var w in Points(skin)){var v=(skin.rootBone?skin.rootBone:skin.transform).InverseTransformPoint(w);if(skinFirst){skinEnvelope=new Bounds(v,Vector3.zero);skinFirst=false;}else skinEnvelope.Encapsulate(v);}}}
 restBounds.Expand(.016f);travel.Expand(.025f);rest.SampleAnimation(model,0);
 var guard=oldGuard;guard.animatedBody=restBounds;guard.clearance=.025f;var body=life.GetComponent<ReefSphereBody>();body.centerOffset=restBounds.center;body.radius=.035f;
 // Place the resting body on a collision-clear patch in its existing moray habitat.
 Physics.SyncTransforms();Vector3 spawn=oldPosition;bool found=false;for(int ring=0;ring<13&&!found;ring++)for(int n=0;n<(ring==0?1:24);n++){var p=oldPosition+new Vector3(Mathf.Cos(n*Mathf.PI/12)*ring*.25f,0,Mathf.Sin(n*Mathf.PI/12)*ring*.25f);if(!guard.RequiredHeight(p,actor.rotation,out float floor))continue;p.y=floor+.006f;var ext=Vector3.Scale(restBounds.extents,actor.lossyScale)*.98f;if(Physics.CheckBox(p+actor.TransformVector(restBounds.center),ext,actor.rotation,1<<8,QueryTriggerInteraction.Ignore))continue;if(!body.Clear(p))continue;spawn=p;found=true;break;}if(!found)throw new Exception("No safe resting moray patch near current habitat");actor.position=spawn;
 var touch=new System.Collections.Generic.List<Collider>();for(int i=0;i<bones.Length;i++){var bone=bones[i];var endpoint=i+1<bones.Length?bones[i+1].position:bone.position+(bone.position-bones[i-1].position)*.8f;var direction=endpoint-bone.position;var go=new GameObject("Moray hand touch "+i);go.layer=2;go.transform.SetParent(bone,false);go.transform.SetPositionAndRotation((bone.position+endpoint)*.5f,Quaternion.FromToRotation(Vector3.up,direction.normalized));var capsule=go.AddComponent<CapsuleCollider>();capsule.isTrigger=true;capsule.direction=1;float scale=Mathf.Max(.00001f,Mathf.Abs(go.transform.lossyScale.x));float radius=Mathf.Lerp(.045f,.012f,i/(float)(bones.Length-1))*wrapper.transform.localScale.x;capsule.radius=radius/scale;capsule.height=Mathf.Max(direction.magnitude+radius*1.4f,radius*2)/Mathf.Abs(go.transform.lossyScale.y);touch.Add(capsule);}
 var behavior=life.gameObject.AddComponent<CurledMorayEncounter>();behavior.animationPlayer=player;behavior.restClip=rest;behavior.swimClip=swim;behavior.skin=skin;behavior.touchVolumes=touch.ToArray();behavior.restBounds=restBounds;behavior.travelBounds=travel;life.stationary=true;behavior.Initialize();Physics.SyncTransforms();
 if(!behavior.CanEscape(actor.position+actor.forward*.5f)){bool escapePatch=false;var preferred=spawn;for(int ring=1;ring<=20&&!escapePatch;ring++)for(int n=0;n<24;n++){var p=preferred+new Vector3(Mathf.Cos(n*Mathf.PI/12)*ring*.25f,0,Mathf.Sin(n*Mathf.PI/12)*ring*.25f);if(!guard.RequiredHeight(p,actor.rotation,out float h))continue;p.y=h+.006f;var ext=Vector3.Scale(restBounds.extents,actor.lossyScale)*.98f;if(Physics.CheckBox(p+actor.TransformVector(restBounds.center),ext,actor.rotation,1<<8,QueryTriggerInteraction.Ignore)||!body.Clear(p))continue;actor.position=p;Physics.SyncTransforms();if(behavior.CanEscape(actor.position+actor.forward*.5f)){escapePatch=true;spawn=p;break;}}if(!escapePatch)throw new Exception("No clear moray escape patch within 5m: "+behavior.LastPlanFailure);}
 skinEnvelope.Expand(.03f);skin.localBounds=skinEnvelope;
 var lod=wrapper.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.015f,new Renderer[]{skin})});lod.RecalculateBounds();foreach(var pair in protectedActors)if(!pair.Key||EditorJsonUtility.ToJson(pair.Key)+EditorJsonUtility.ToJson(pair.Key.transform)!=pair.Value)throw new Exception("Unrelated actor changed");
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllText("Renders/CurledMorayEncounter/Placement.txt","Previous root="+oldPosition+" resting root="+spawn+"\nRest bounds="+restBounds+"\nTravel bounds="+travel+"\n");Capture();Validate();Debug.Log("CURLED_MORAY_INTEGRATED");
 }
 public static void Validate(){
 EditorSceneManager.OpenScene(Scene);var life=Actor();var behavior=life.GetComponent<CurledMorayEncounter>();if(!behavior||behavior.skin.sharedMesh.triangles.Length/3!=24000||life.grabbable||life.danger)throw new Exception("Moray identity or mesh invalid");if(life.GetComponent<WreckCreature>().enabled||life.GetComponentsInChildren<YellowMorayMotion>().Any(m=>m.enabled))throw new Exception("Conflicting moray animation owner");
 behavior.Initialize();Physics.SyncTransforms();var start=life.transform.position;var hand=behavior.touchVolumes[2].ClosestPoint(start+Vector3.up*.3f);behavior.Step(.05f,hand+Vector3.up*.4f);if(behavior.State!=CurledMorayEncounter.Phase.Resting)throw new Exception("Reacted to proximity");behavior.Step(.05f,hand);if(behavior.State==CurledMorayEncounter.Phase.Resting)throw new Exception("Touch could not plan escape from original habitat: "+behavior.LastPlanFailure);
 var phases=new System.Collections.Generic.HashSet<string>();float minMargin=float.MaxValue;int vertices=0;var guard=life.GetComponent<ReefAnimalClearance>();var body=life.GetComponent<ReefSphereBody>();for(int f=0;f<1400&&behavior.CompletedEscapes==0;f++){behavior.Step(.05f);guard.Enforce();Physics.SyncTransforms();phases.Add(behavior.State.ToString());if(!body.Clear(life.transform.position))throw new Exception("Moray body overlap "+behavior.State+" at "+life.transform.position);if(!guard.RequiredHeight(life.transform.position,life.transform.rotation,out float height))throw new Exception("Missing seabed");minMargin=Mathf.Min(minMargin,life.transform.position.y-height);if(f%8==0)foreach(var p in Points(behavior.skin)){var v=life.transform.InverseTransformPoint(p);var allowed=guard.animatedBody;allowed.Expand(.01f);if(!allowed.Contains(v))throw new Exception("Animated vertex outside clearance in "+behavior.State);vertices++;}}
 float moved=Vector3.ProjectOnPlane(life.transform.position-start,Vector3.up).magnitude;if(behavior.CompletedEscapes!=1||behavior.State!=CurledMorayEncounter.Phase.Resting||moved<1.5f)throw new Exception("Moray did not settle elsewhere: "+behavior.State+" completed="+behavior.CompletedEscapes+" displacement="+moved);if(behavior.RequestTouch(hand))throw new Exception("Cooldown failed");if(!guard.RequiredHeight(life.transform.position,life.transform.rotation,out float floor)||Mathf.Abs(life.transform.position.y-floor)>.04f)throw new Exception("Moray did not ground");
 File.WriteAllText("Renders/CurledMorayEncounter/Validation.txt","24,000 triangles; 22 bones; curled-rest and straight-swim clips.\nHand proximity alone ignored; hand contact triggered escape.\nStates="+string.Join(", ",phases)+"\nHorizontal displacement="+moved+" m; path travel="+behavior.LastTravel+" m; settled clearance margin="+(life.transform.position.y-floor)+" m; minimum floor margin="+minMargin+" m.\nAnimated vertices checked="+vertices+"; sphere/reef and animated bounds passed. Cooldown passed.\n");EditorSceneManager.OpenScene(Scene);Debug.Log("CURLED_MORAY_VALIDATED");
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);var actor=Actor();var behavior=actor.GetComponent<CurledMorayEncounter>();behavior.Initialize();var camera=Camera.main;var optics=camera.GetComponent<ReefOptics>();if(optics)optics.enabled=false;var center=behavior.skin.bounds.center;camera.transform.position=center+actor.transform.right*2+Vector3.up*1.5f;camera.transform.LookAt(center);camera.fieldOfView=50;ReefCorrectionAudit.Capture(camera,"Renders/CurledMorayEncounter/Resting.png");}
 public static void ValidateEdges(){
 EditorSceneManager.OpenScene(Scene);var life=Actor();var b=life.GetComponent<CurledMorayEncounter>();b.Initialize();Physics.SyncTransforms();var guard=life.GetComponent<ReefAnimalClearance>();
 for(int cycle=0;cycle<2;cycle++){if(cycle>0)for(int i=0;i<110;i++)b.Step(.05f);Physics.SyncTransforms();var hand=b.touchVolumes[2].ClosestPoint(life.transform.position+Vector3.up*.3f);if(cycle==0)b.Step(.05f,right:hand);else b.Step(.05f,leftTip:hand);if(b.State==CurledMorayEncounter.Phase.Resting)throw new Exception("Repeat/right/fingertip touch failed: "+b.LastPlanFailure);for(int f=0;f<1500&&b.CompletedEscapes<cycle+1;f++){b.Step(.05f);guard.Enforce();Physics.SyncTransforms();if(!life.GetComponent<ReefSphereBody>().Clear(life.transform.position))throw new Exception("Repeat escape collision");}if(b.CompletedEscapes!=cycle+1||b.State!=CurledMorayEncounter.Phase.Resting)throw new Exception("Repeat escape did not settle");}
 for(int i=0;i<110;i++)b.Step(.05f);var start=life.transform.position;var obstacle=GameObject.CreatePrimitive(PrimitiveType.Cube);obstacle.name="Validation-only blocked escape";obstacle.layer=8;obstacle.transform.position=start;obstacle.transform.localScale=Vector3.one*20;Physics.SyncTransforms();bool accepted=b.RequestTouch(start+Vector3.forward);UnityEngine.Object.DestroyImmediate(obstacle);Physics.SyncTransforms();if(accepted||b.State!=CurledMorayEncounter.Phase.Resting||life.transform.position!=start)throw new Exception("Blocked route should preserve resting pose");
 File.WriteAllText("Renders/CurledMorayEncounter/EdgeValidation.txt","Right palm contact and later fingertip contact each completed a separate escape/ground/curl cycle. Repeated escape collision checks passed. A fully obstructed route declined the reaction without teleporting or changing the resting pose.\n");EditorSceneManager.OpenScene(Scene);Debug.Log("MORAY_EDGE_CASES_VALIDATED");
 }
 public static void CaptureSequence(){
 EditorSceneManager.OpenScene(Scene);var life=Actor();var b=life.GetComponent<CurledMorayEncounter>();b.Initialize();Physics.SyncTransforms();var cam=Camera.main;var optics=cam.GetComponent<ReefOptics>();if(optics)optics.enabled=false;var hand=b.touchVolumes[2].ClosestPoint(life.transform.position+Vector3.up*.3f);if(!b.RequestTouch(hand))throw new Exception("Preview escape could not start");var center=(life.transform.position+b.Destination)*.5f;cam.transform.position=center+life.transform.right*5+Vector3.up*5;cam.transform.LookAt(center);cam.fieldOfView=55;Directory.CreateDirectory("Renders/CurledMorayEncounter/Sequence");
 int frame=0;for(int f=0;f<1200;f++){b.Step(.05f);life.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();if(f%4==0){ReefCorrectionAudit.Capture(cam,"Renders/CurledMorayEncounter/Sequence/Frame"+frame.ToString("D3")+".png");frame++;}if(b.CompletedEscapes>0&&f>20)break;}ReefCorrectionAudit.Capture(cam,"Renders/CurledMorayEncounter/Settled.png");File.WriteAllText("Renders/CurledMorayEncounter/SequenceFrames.txt",frame.ToString());EditorSceneManager.OpenScene(Scene);
 }
 public static void FinalizeIntegration(){Run();ValidateEdges();CaptureSequence();}
 public static void CheckSwimPose(){
 EditorSceneManager.OpenScene(Scene);var life=Actor();var b=life.GetComponent<CurledMorayEncounter>();var bones=b.skin.bones;b.restClip.SampleAnimation(b.animationPlayer.gameObject,0);var local=bones.Select(t=>t.localPosition).ToArray();b.swimClip.SampleAnimation(b.animationPlayer.gameObject,1);float difference=bones.Select((t,i)=>(t.localPosition-local[i]).magnitude).Max();b.restClip.SampleAnimation(b.animationPlayer.gameObject,0);b.Initialize();Physics.SyncTransforms();var hand=b.touchVolumes[2].ClosestPoint(life.transform.position+Vector3.up*.3f);if(!b.RequestTouch(hand))throw new Exception("No preview route");for(int f=0;f<400&&b.State!=CurledMorayEncounter.Phase.Swimming;f++){b.Step(.05f);life.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();}for(int f=0;f<50;f++){b.Step(.05f);life.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();}
 var points=bones.Select(t=>life.transform.InverseTransformPoint(t.position)).ToArray();var box=new Bounds(points[0],Vector3.zero);foreach(var q in points)box.Encapsulate(q);File.WriteAllText("Renders/CurledMorayEncounter/SwimPose.txt","State="+b.State+" local spine extent="+box.size+" max local joint translation between rest and swim clips="+difference);
 var cam=Camera.main;var optics=cam.GetComponent<ReefOptics>();if(optics)optics.enabled=false;var center=b.skin.bounds.center;cam.transform.position=center+life.transform.right*2+Vector3.up*1.5f;cam.transform.LookAt(center);cam.fieldOfView=50;ReefCorrectionAudit.Capture(cam,"Renders/CurledMorayEncounter/Swimming.png");EditorSceneManager.OpenScene(Scene);
 }
